<?php
declare(strict_types=1);
namespace GreatMarketrealmTabletop\Tests\Unit\Tabletop\Light;
use PHPUnit\Framework\TestCase;
final class KeepersLanternRackRegressionTest extends TestCase { private function source(string $path): string { return (string)file_get_contents(dirname(__DIR__,4).'/'.$path); } public function test_lantern_rack_is_keeper_only_presentation(): void { $s=$this->source('app/Tabletop/Views/chamber.php');self::assertStringContainsString("The Keeper's Lantern Rack",$s);self::assertStringContainsString('data-keeper-light-kind="torch"',$s);self::assertStringContainsString('data-keeper-light-kind="magical"',$s); } public function test_environmental_lights_reuse_fog_projector(): void { $s=$this->source('app/Tabletop/Fog/Services/FogOfWarProjector.php');self::assertStringContainsString('instanceof EnvironmentalLight',$s);self::assertStringContainsString("\$sourceKind = 'environmental'",$s);self::assertStringContainsString('$mapper->visibleAround($scene, $lightSource, $barriers, $lightRadius)',$s); } public function test_keeper_endpoint_requires_dungeon_master(): void { $s=$this->source('app/Tabletop/Http/EnvironmentalLightAjaxController.php');self::assertStringContainsString('!$member->isDungeonMaster()',$s);self::assertStringContainsString("gmrt_tend_environmental_light",$this->source('app/Tabletop/TabletopServiceProvider.php')); } public function test_environmental_lights_are_scene_owned_and_cleaned(): void { self::assertStringContainsString("'gmrt_environmental_lights'",$this->source('app/Tabletop/Atlas/Services/SceneShelfCleaner.php'));self::assertStringContainsString('forScene($tableId, $activeScene->id())',$this->source('app/Tabletop/Services/TabletopChamber.php')); } public function test_placement_honours_private_preparation_scene(): void { $s=$this->source('assets/js/tabletop.js');self::assertStringContainsString('scene_id:preparationSceneId||projectedSceneId',$s);self::assertStringContainsString("light_action: 'place'",$s); } public function test_lantern_roster_exists_before_initial_fog_render(): void { $s=$this->source('assets/js/tabletop.js');$roster=strpos($s,"const keeperLightRoster = document.querySelector('[data-keeper-light-roster]')");$render=strpos($s,'renderFog();');self::assertNotFalse($roster);self::assertNotFalse($render);self::assertLessThan($render,$roster); } public function test_lantern_placement_owns_map_click_in_capture_phase(): void { $s=$this->source('assets/js/tabletop.js');self::assertStringContainsString('Lantern placement owns the next battlefield click in capture phase.',$s);self::assertStringContainsString("scene_id: preparationSceneId || projectedSceneId",$s);self::assertStringContainsString('}, true);',$s);self::assertStringContainsString('Placement remains armed; click the map to try again or cancel.',$s); } }
